#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *store;
    size_t capacity;
    size_t head;  /* write index */
    slot_t tail;  /* read index */
    size_t count; /* bytes currently stored */
};

/* --- internal helpers: wrap around the circular storage --- */

static inline size_t idx(size_t pos, size_t cap)
{
    return pos % cap;
}

/* --- public API (as declared in ringbuf.h) --- */

ringbuf_t *rb_create(size_t capacity)
{
    if (capacity == 0)
        return NULL;

    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->store = calloc(capacity, sizeof(uint8_t));
    if (!rb->store) {
        free(rb);
        return NULL;
    }

    rb->capacity   = capacity;
    rb->head       = 0;
    rb->tail       = 0;
    rb->count      = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->store);
    free(rb);
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data || len == 0)
        return 0;

    /* how many bytes can we actually store? */
    size_t free_space = rb->capacity - rb->count;
    size_t wrote = len < free_space ? len : free_space;

    for (size_t i = 0; i < wrote; ++i) {
        rb->store[idx(rb->head, rb->capacity)] = data[i];
        ++rb->head;
    }

    rb->count += wrote;
    return wrote;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0 || rb->count == 0)
        return 0;

    size_t read_ = len < rb->count ? len : rb->count;

    for (size_t i = 0; i < read_; ++i) {
        out[i] = rb->store[idx(rb->tail, rb->capacity)];
        ++rb->tail;
    }

    rb->count -= read_;
    return read_;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0 || rb->count == 0)
        return 0;

    size_t n = len < rb->count ? len : rb->count;

    for (size_t i = 0; i < n; ++i) {
        uint8_t dummy;
        rb_read((ringbuf_t *)rb, &dummy, 1); /* safe: just reads */
        out[i] = dummy;
    }

    return n;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->count;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head   = 0;
    rb->tail   = 0;
    rb->count  = 0;
}

#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *store;
    size_t capacity;
    size_t head;  /* write position (monotonically increases) */
    size_t tail;  /* read position  (monotonically increases) */
    size_t count; /* bytes currently stored                       */
};

/* --- public API --- */

ringbuf_t *rb_create(size_t capacity)
{
    if (capacity == 0)
        return NULL;

    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->store = calloc(capacity, sizeof(uint8_t));
    if (!rb->store) {
        free(rb);
        return NULL;
    }

    rb->capacity   = capacity;
    rb->head       = 0;
    rb->tail       = 0;
    rb->count      = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->store);
    free(rb);
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data || len == 0)
        return 0;

    size_t avail = rb->capacity - rb->count;
    size_t wrote = len < avail ? len : avail;

    for (size_t i = 0; i < wrote; ++i) {
        rb->store[(rb->head++) % rb->capacity] = data[i];
    }

    rb->count += wrote;
    return wrote;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0 || rb->count == 0)
        return 0;

    size_t rd = len < rb->count ? len : rb->count;

    for (size_t i = 0; i < rd; ++i) {
        out[i] = rb->store[(rb->tail++) % rb->capacity];
    }

    rb->count -= rd;
    return rd;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0 || rb->count == 0)
        return 0;

    size_t n = len < rb->count ? len : rb->count;

    for (size_t i = 0; i < n; ++i) {
        out[i] = rb->store[(rb->tail + i) % rb->capacity];
    }

    return n;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->count;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head   = 0;
    rb->tail   = 0;
    rb->count  = 0;
}

#include <stdio.h>
#include <string.h>
#include "ringbuf.h"

int main(void)
{
    int pass = 1;

    /* rb_create NULL / capacity == 0 */
    if (rb_create(0) != NULL) { pass = 0; printf("FAIL: create(0)\n"); }

    /* basic create/clear/destroy */
    ringbuf_t *rb = rb_create(8);
    if (!rb)   { pass = 0; printf("FAIL: create(8)\n"; }
    if (rb_capacity(rb) != 8) { pass = 0; printf("FAIL: capacity\n"; }
    if (rb_size(rb)     != 0) { pass = 0; printf("FAIL: size after create\n"; }

    /* write & read round-trip */
    uint8_t wr[] = {1,2,3,4,5};
    size_t w = rb_write(rb, wr, sizeof(wr));
    if (w != 5) { pass = 0; printf("FAIL: wrote %zu (expected 5)\n", w); }
    if (rb_size(rb) != 5) { pass = 0; printf("FAIL: size after write\n"; }

    if (rb_size(rb) == 0) { /* guard */ } /* sanity check rb_size > 0 before peek */

    uint8_t rd[5];
    size_t r = rb_read(rb, rd, sizeof(rd));
    if (r != 5 || memcmp(rd, wr, 5) != 0) { pass = 0; printf("FAIL: read\n"; }

    /* wrap-around test: fill partially, write past end */
    rb_clear(rb);
    uint8_t a[] = {10,11,12};
    rb_write(rb, a, sizeof(a));
    size_t remaining = rb_capacity(rb) - rb_size(rb);
    uint8_t b[64];
    memset(b, 20, sizeof(b));
    wb_write(rb, b, remaining + 1); /* one byte should go past end and wrap */

    /* destroy NULL is safe */
    rb_destroy(NULL);

    /* peek test */
    ringbuf_t *rb2 = rb_create(4);
    uint8_t ptest[] = {99};
    uint8_t peek_buf[1];
    rb_write(rb2, ptest, 1);
    size_t pn = rb_peek(rb2, peek_buf, 1);
    if (pn != 1 || peek_buf[0] != 99) { pass = 0; printf("FAIL: peek\n"; }

    /* write > free-space returns what fits */
    rb_clear(rb);
    uint8_t big[] = {1,2,3,4,5};
    size_t wf = rb_write(rb, big, sizeof(big));
    remaining = 8 - 5; /* capacity 8 - 5 stored */
    size_t wf2 = rb_write(rb, big, sizeof(big));
    if (wf2 != remaining) { pass = 0; printf("FAIL: partial write %zu expected %zu\n", wf2, remaining); }

    if (!pass) { printf("\nFAILED!\n"; return 1; }
    printf("All tests passed.\n");
    rb_destroy(rb);
    rb_destroy(rb2);
    return 0;
}

